viewer:
(async () => {
const shared = (await import("./viewer-context.js")).default;
shared.AtlasTools = (await import("./atlas-tools.js")).default;
const app = (await import("./app.js"));
const workspace = (await import("./workspace-tools.js"));
const inference = (await import("./inference.js"));
app.initialize();
workspace.mount(app);
inference.mount();
})();

